class Cart:
    def __init__(self, free_shipping_threshold: float = 100.0, shipping_cost: float = 15.0) -> None:
        self.free_shipping_threshold = float(free_shipping_threshold)
        self.shipping_cost = float(shipping_cost)
        self.items: list[dict[str, float | int]] = []
        self.percentage_discounts: list[float] = []
        self.vouchers: list[float] = []

    def add(self, name: str, unit_price: float, quantity: int = 1) -> None:
        if quantity <= 0:
            raise ValueError("Quantity must be greater than zero.")
        self.items.append({
            "name": name,
            "unit_price": float(unit_price),
            "quantity": int(quantity)
        })

    def apply_discount(self, percent: float) -> None:
        """Register a percentage discount on the whole cart. Can be called several times."""
        self.percentage_discounts.append(float(percent))

    def apply_voucher(self, amount: float) -> None:
        """Register a voucher worth a fixed amount. Can be called several times."""
        self.vouchers.append(float(amount))

    def total(self) -> float:
        """Amount to pay: items after discounts plus shipping."""
        items_subtotal = sum(item["unit_price"] * item["quantity"] for item in self.items)

        if items_subtotal <= 0:
            return 0.0

        max_savings = 0.0

        # Calculate maximum potential savings from percentage discounts
        for percent in self.percentage_discounts:
            # Discount can save at most the items subtotal
            savings = max(0.0, items_subtotal * (percent / 100.0))
            if savings > items_subtotal:
                savings = items_subtotal
            if savings > max_savings:
                max_savings = savings

        # Calculate maximum potential savings from vouchers
        for voucher in self.vouchers:
            savings = max(0.0, voucher)
            if savings > items_subtotal:
                savings = items_subtotal
            if savings > max_savings:
                max_savings = savings

        discounted_items_total = items_subtotal - max_savings

        # Shipping applies if the discounted subtotal is below the threshold
        shipping = 0.0 if discounted_items_total >= self.free_shipping_threshold else self.shipping_cost

        return round(discounted_items_total + shipping, 2)
```

